/* Fleet turret/enemy state update: refreshes the hit reaction, fires the aim query and sets the lock flags. */
void update_robot_dog_hit_reaction_and_target_detection(Moby *moby, int arg) {
    Data_2F1558 *d;
    Hit_2F1558 *q;
    float tmp[4];
    int x;
    float y;
    float ang;
    int r;
    float yaw;
    float ang2;

    d = (Data_2F1558 *)moby->pvars;
    if (moby->state == 0) {
        return;
    }
    if (d->i38 != 0) {
        d->f1D4 = truncate_float_to_s32_r(multiply_global_factor(random_float_between(180.0f, 240.0f)));
        d->i38 = 0;
    }
    update_float_countdown(&d->f1D4);
    y = 0;
    q = (Hit_2F1558 *)MobyGetHitMessage(moby, 0x330000, 0);
    ComputeHitResponse(moby, q, &d->f20, 0, &x, &y, 0, 4);
    if (x != 1 && moby->state != 15) {
        d->f20 -= y;
        d->f130 = g_frame_time_sq * 42.0f;
        d->f134 = g_frame_time_sq * 24.0f;
        d->b15D = 0;
        d->i144 = 9;
        d->f13C = g_frame_time * 15.7f;
        d->f138 = g_frame_time * 19.0f;
        d->f170 = -1.0f;
        d->f174 = -1.0f;
        *(q128_2F1558 *)tmp = *(q128_2F1558 *)q->pos;
        HeadingFromVector(tmp, &ang, &d->f138, &d->f13C);
        if (q != 0 && q->moby != 0 && q->moby->oclass == 0x63) {
            ang = fast_atan2(d->f1F0 - moby->pos.x, d->f1F4 - moby->pos.y);
        }
        InitKnockback(ang, moby, d->v120, 0xB, 1, 0);
        moby->state = 15;
        d->b117 = 0xF0;
        RerollEffectCounter(moby, d->h110);
    }
    moby->hit_slot = 0xFF;
    if (arg != 0) {
        return;
    }
    if (FindNearestEligibleMoby(128.0f, (char *)moby, d->v180, 0, 0, 0, 0) == 2) {
        return;
    }
    if (FastVecDist(&moby->pos, d->v1B0) < 64.0f) {
        ang2 = fast_atan2(d->v180[0] - moby->pos.x, d->v180[1] - moby->pos.y);
        yaw = FastDiffRots(moby->rot.z, ang2);
        qcopy(tmp, &moby->pos);
        tmp[2] += 1.0f;
        r = coll_line(tmp,&((struct Hero *)((char *)&hero_globals_base + 0xE1D))->motion.body_center, 2, 0, 0) == 0;
        d->b1E4 = r;
        if (yaw < 1.0471976f) {
            d->b1E4 = r << 1;
        }
    }
}
