extern int process_moby_suck_cannon_suction_pos(void *, void *, void *, float) __asm__("func_L00_002DCDA8");
/* One of a class's Suck Cannon hooks (grab, place or fire), which the catalogue folds: each copy
   calls its own one, the fire with (moby, velocity, target, height), so the arguments go on as
   they came (retail touches none of a1, a2 and $f12 before its call). */
int enemy_stun_update(unsigned char *moby, void *pos, void *target, float h) {
    int result = process_moby_suck_cannon_suction_pos(moby, pos, target, h);
    if (result) {
        moby[0x20] = 12;
    } else if (moby[0x20] == 12) {
        moby[0x20] = 6;
        if (moby[0x53] != 7) {
            int value = scale_ticks(10);
            MobyBlendAnimation(moby, 7, 0, value);
        }
    }
    return result;
}
/* Cancels the Suck Cannon's suction on the moby and puts it into state 12. */
int cancel_suck_cannon_suction_and_set_state_12(char *a) {
    int r = cancel_suck_cannon_suction(a);
    a[0x20] = 12;
    return r;
}
