/* The turret's eased part (func_L00_00263950's second argument) and where it sits in the moby's data. */
typedef struct {
    char pad0[0x64];
    float pitch;
    float yaw;
} AimPart_1BB0;

typedef struct {
    char pad0[0x230];
    AimPart_1BB0 part;
} AimData_1BB0;

/* Aims the turret at the hero: yaw and pitch to him, clamped, become the eased part's targets. */
void update_robot_dog_aim_joint(char *moby) {
    AimData_1BB0 *d = ((AimData_1BB0 *)((Moby *)moby)->pvars);
    float accel = 0.02f;
    float speed = 0.3f;
    float tmp[4];
    float v[4];
    float yaw;
    float pitch;
    qcopy(tmp, moby + 0x10);
    tmp[2] += 0.5f;
    FastVecSub(v,&((struct Hero *)((char *)&hero_globals_base + 0xE1D))->motion.body_center, tmp);
    yaw = FastSubRots(fast_atan2(v[0], v[1]), ((Moby *)moby)->rot.z);
    pitch = -fast_atan2(vec_length_xy(v), v[2]);
    if (yaw > 1.0471976f) {
        yaw = 1.0471976f;
    } else if (yaw < -1.0471976f) {
        yaw = -1.0471976f;
    }
    if (pitch > 0.5235988f) {
        pitch = 0.5235988f;
    } else if (pitch < -0.5235988f) {
        pitch = -0.5235988f;
    }
    d->part.pitch = pitch;
    d->part.yaw = yaw;
    EaseManipulatorOffsets(moby, (char *)&d->part, 0, accel * g_frame_scale_sq, speed * g_frame_scale_sq);
}
