// Pulses a moby's colour from a random phase and queues its draw callback.
void update_robot_dog_glow_effects(unsigned char *moby) {
    struct RobotDogVars *data;
    int glow_pulse_period_frames;
    int alpha;
    int mode;
    int i;
    int x, y, z;
    int r, g, b;
    float glow_pulse_sine;
    int color;

    /* Period and base colour by state range; both ranges have the same values in this build. */
    if (((struct Moby *)moby)->state < 16) {
        glow_pulse_period_frames = 0xAA;
        r = 0x32;
        g = 0xB4;
        b = 0x14;
    } else {
        glow_pulse_period_frames = 0xAA;
        r = 0x32;
        g = 0xB4;
        b = 0x14;
    }
    data = (struct RobotDogVars *)((struct Moby *)moby)->pvars;
    glow_pulse_period_frames = scale_ticks(glow_pulse_period_frames);
    alpha = 0x80;
    mode = 0;
    switch (((struct Moby *)moby)->state) {
    case 4:
    case 5:
    case 6:
        mode = 1;
        break;
    case 7:
    case 8:
    case 9:
    case 10:
    case 11:
    case 13:
    case 14:
    case 15:
        mode = 2;
        break;
    case 12:
        mode = -1;
        break;
    }
    if (mode >= 0) {
        if (mode == 2) {
            glow_pulse_period_frames = scale_ticks(0x32);
        } else if (mode == 1) {
            glow_pulse_period_frames = scale_ticks(0x5A);
        }
        glow_pulse_sine = FastSin(((float)(fleet_frame_count % glow_pulse_period_frames) / IntToFloat(glow_pulse_period_frames)) * 2.0f * 3.1415927f +
                     -3.1415927f);
        x = truncate_float_to_s32_r(glow_pulse_sine * 20.0f);
        y = truncate_float_to_s32_r(glow_pulse_sine * 70.0f);
        z = truncate_float_to_s32_r(glow_pulse_sine * 10.0f);
        r += x;
        g += y;
        b += z;
        if (r > 255) {
            r = 255;
        }
        if (g > 255) {
            g = 255;
        }
        if (mode == 2) {
            color = (alpha << 24) | (b << 16) | ((r / 2) << 8) | g;
        } else if (mode != 0) {
            color = (alpha << 24) | (b << 16) | ((r / 2) << 8) | g;
        } else {
            color = (alpha << 24) | (b << 16) | (g << 8) | r;
        }
        ((struct Moby *)moby)->glow_color = FastTweenColor(((struct Moby *)moby)->glow_color, color, 0.1f);
        for (i = 0; i < 3; i++) {
            Moby_GetJointWorldPos(moby, i + 1, &data->glow_pos[i]);
        }
        AddDrawCallback(draw_three_moby_effect_quads, moby);
    }
}
extern void draw_offset_textured_effect_quad(void *, int, float, float);
/* Draws three glow quads in the moby's glow color at the points stored in its pvars. */
void draw_three_moby_effect_quads(char *m) {
    int v = (((Moby *)m)->glow_color & 0xFFFFFF) | 0x30000000;
    char *p = (char *)((struct RobotDogVars *)((Moby *)m)->pvars)->glow_pos;
    int i;
    for (i = 2; i >= 0; i--) {
        draw_offset_textured_effect_quad(p, v, 0.2f, 0.08f);
        p += 0x10;
    }
}
