/* Advances a moby along a three-curve path and updates its heading, pitch and speed. */
int update_shuttle_travel_and_camera(char *moby, int idx) {
    float m[4], pos[4];
    struct Dat_3CC0 *d = ((struct Dat_3CC0 *)((Moby *)moby)->pvars);
    Path_3CC0 *c1 = ((Path_3CC0 **)fleet_paths)[d->a[idx]];
    Path_3CC0 *c2 = ((Path_3CC0 **)fleet_paths)[d->b[idx]];
    Path_3CC0 *c3 = ((Path_3CC0 **)fleet_paths)[d->c[idx]];
    float t, f, t1, t2, t3, ang, turn;
    int i1, i2, i3;

    ApproachValue(&d->fA4, 1.0f, 1.0f / (float)scale_ticks(0x384));
    t = d->fA4 * (float)(c1->n - 1);
    i1 = truncate_float_to_s32_r(t);
    f = (float)i1;
    t1 = t - f;
    t2 = d->fA4 * 1.02f;
    if (t2 > 1.0f) t2 = 1.0f;
    t = t2 * (float)(c2->n - 1);
    i2 = truncate_float_to_s32_r(t);
    t2 = t - (float)i2;
    t = d->fA4 * (float)(c3->n - 1);
    t3 = t - f;
    i3 = truncate_float_to_s32_r(t);
    lerp_vector(pos, &c1->p[i1], &c1->p[i1 + 1], t1);
    lerp_vector(moby + 0x10, &c3->p[i3], &c3->p[i3 + 1], t3);
    set_camera_position(pos);
    {
        char *base = fleet_camera_points + (d->e84 << 7);
        Hero_ResetToPosition(base + 0x30, base + 0x70, 0x72, 0);
    }
    if (i3 > 0) {
        ang = fast_atan2(c3->p[i3].x - c3->p[i3 - 1].x, c3->p[i3].y - c3->p[i3 - 1].y);
        ((Moby *)moby)->rot.z = FastAddRots(FastSubRots(fast_atan2(c3->p[i3 + 1].x - c3->p[i3].x, c3->p[i3 + 1].y - c3->p[i3].y), ang) * t3, ang);
        ang = -fast_atan2(vec_distance_xy(&c3->p[i3 - 1], &c3->p[i3]), c3->p[i3].z - c3->p[i3 - 1].z);
        ((Moby *)moby)->rot.y = FastAddRots(FastSubRots(-fast_atan2(vec_distance_xy(&c3->p[i3], &c3->p[i3 + 1]), c3->p[i3 + 1].z - c3->p[i3].z), ang) * t3, ang);
        ((Moby *)moby)->rot.y = ((Moby *)moby)->rot.y * FastCos(d->f88);
        ((Moby *)moby)->rot.z = FastAddRots(((Moby *)moby)->rot.z, d->f88);
    } else {
        ((Moby *)moby)->rot.y = -fast_atan2(vec_distance_xy(&c3->p[0], &c3->p[1]), c3->p[1].z - c3->p[0].z);
        ((Moby *)moby)->rot.z = fast_atan2(c3->p[1].x - c3->p[0].x, c3->p[1].y - c3->p[0].y);
    }
    if (i1 > 0 && i2 > 0) {
        clear_u64_value(m);
        ang = fast_atan2(c2->p[i2].x - pos[0], c2->p[i2].y - pos[1]);
        m[2] = FastAddRots(FastSubRots(fast_atan2(c2->p[i2 + 1].x - pos[0], c2->p[i2 + 1].y - pos[1]), ang) * t2, ang);
        ang = -fast_atan2(vec_distance_xy(pos, &c2->p[i2]), c2->p[i2].z - pos[2]);
        m[1] = FastAddRots(FastSubRots(-fast_atan2(vec_distance_xy(pos, &c2->p[i2 + 1]), c2->p[i2 + 1].z - pos[2]), ang) * t2, ang);
        set_camera_rotation(m);
    }
    ((Moby *)moby)->scale = *(float *)(*(char **)(moby + 0x24) + 0x24) *
        (d->f9C - (d->f9C - d->fA0) * d->fA4);
    if (d->fA4 > 0.8f) {
        turn = g_frame_time_sq * 12.566371f;
        SteerAngleWithVelocity(&d->f88, &d->f8C, 3.1415927f, turn, turn, g_frame_time * 6.2831855f);
    }
    return d->fA4 == 1.0f;
}
