/* Draws the Drek's Fleet reflection/backdrop quads around a moby. */
void draw_fleet_backdrop_quads(char *moby) {
    Pkt pkt;
    u128_2F4E30 vv[4];
    struct FleetBackdropVars *data = (struct FleetBackdropVars *)((Moby *)moby)->pvars;
    char *pos;
    int i;
    int k;
    int j;
    u128_2F4E30 *vb;
    float *pu;
    float *pv;
    VU1_addGSregister(0x47, 0x513F1);
    vb = &vv[2];
    pos = (char *)&data->far_pos;
    pu = &pkt.uv[0];
    pv = &pkt.uv[1];
    fleet_view_params_field_a4 = 8192000.0f;
    data->far_pos.y = -8000.0f;
    for (i = 0; i < 2; i++) {
        FastVecSub(vb, &data->anchor, pos);
        FastVecSub(&vv[0], &data->anchor, fleet_camera_pos);
        FastVecSub(&vv[1], pos, fleet_camera_pos);
        FastVecCross(&vv[0], &vv[0], vb);
        vec_scale_to_length(&vv[0], &vv[0], fleet_backdrop_beam_widths[i]);
        FastVecCross(&vv[1], &vv[1], vb);
        vec_scale_to_length(&vv[1], &vv[1], data->width);
        *(long *)&pkt.q[4] = 0x0000FF9000000260LL;
        *(long *)&pkt.q[6] = 0x0000008000000048LL;
        *(long *)&pkt.q[0] = 0;
        pkt.col[3] = *(int *)&fleet_backdrop_beam_color;
        pkt.col[2] = *(int *)&fleet_backdrop_beam_color;
        pkt.col[1] = *(int *)&fleet_backdrop_beam_color;
        pkt.col[0] = *(int *)&fleet_backdrop_beam_color;
        {
            float *qu = &pkt.uv[0];
            float *qv = &pkt.uv[1];
            int m;
            for (m = 0; m < 4; m++) {
                qu[m * 2] = fleet_backdrop_beam_uvs[m * 2];
                qv[m * 2] = fleet_backdrop_beam_uvs[m * 2 + 1];
            }
        }
        FastVecSub(&vv[3], &data->anchor, &vv[0]);
        pkt.m[0] = vv[3];
        FastVecAdd(&vv[3], &data->anchor, &vv[0]);
        pkt.m[1] = vv[3];
        FastVecSub(&vv[3], pos, &vv[1]);
        pkt.m[2] = vv[3];
        FastVecAdd(&vv[3], pos, &vv[1]);
        pkt.m[3] = vv[3];
        *(long *)&pkt.q[2] = GetEffectTex(fleet_backdrop_beam_textures[i]);
        for (j = 0; j < 4; j++) {
            pu[j * 2] = fleet_backdrop_beam_uvs[j * 2] + fleet_backdrop_beam_uv_scroll[i];
            pv[j * 2] = fleet_backdrop_beam_uvs[j * 2 + 1];
        }
        fleet_backdrop_beam_uv_scroll[i] += *(float *)((char *)&fleet_backdrop_beam_scroll_speeds + i * 4) * frame_delta_time;
        draw_world_quad(&pkt, 0, 0);
    }
    *(long *)&pkt.q[2] = GetEffectTex(0x2F);
    for (k = 0; k < 5; k++) {
        float s = fleet_backdrop_glow_sizes[k];
        float ang = fleet_backdrop_glow_angles[k];
        float x = data->far_pos.x - s * 0.5f;
        float z;
        ((float *)&pkt)[0] = x;
        ((float *)&pkt)[1] = data->far_pos.y + 1000.0f;
        z = data->far_pos.z + s * 0.5f;
        ((float *)&pkt)[3] = 1.0f;
        ((float *)&pkt)[2] = z;
        pkt.m[3] = pkt.m[0];
        pkt.m[2] = pkt.m[0];
        pkt.m[1] = pkt.m[0];
        ((float *)&pkt)[0] = x + 0.0f;
        ((float *)&pkt)[2] = z + 0.0f;
        ((float *)&pkt)[4] = ((float *)&pkt)[4] + 0.0f;
        ((float *)&pkt)[6] = ((float *)&pkt)[6] - s;
        ((float *)&pkt)[8] = ((float *)&pkt)[8] + s;
        ((float *)&pkt)[10] = ((float *)&pkt)[10] + 0.0f;
        ((float *)&pkt)[12] = ((float *)&pkt)[12] + s;
        ((float *)&pkt)[14] = ((float *)&pkt)[14] - s;
        pkt.uv[0] = FastSin(FastAddRots(ang, 4.712389f)) * 0.5f + 0.5f;
        pkt.uv[1] = FastCos(FastAddRots(ang, 4.712389f)) * 0.5f + 0.5f;
        pkt.uv[2] = FastSin(FastAddRots(ang, 3.1415927f)) * 0.5f + 0.5f;
        pkt.uv[3] = FastCos(FastAddRots(ang, 3.1415927f)) * 0.5f + 0.5f;
        pkt.uv[4] = FastSin(ang) * 0.5f + 0.5f;
        pkt.uv[5] = FastCos(ang) * 0.5f + 0.5f;
        pkt.uv[6] = FastSin(FastAddRots(ang, 1.5707964f)) * 0.5f + 0.5f;
        pkt.uv[7] = FastCos(FastAddRots(ang, 1.5707964f)) * 0.5f + 0.5f;
        {
            int c = FastTweenColor(fleet_backdrop_glow_colors_from[k], fleet_backdrop_glow_colors_to[k], fleet_backdrop_glow_color_blend[k]);
            pkt.col[3] = c;
            pkt.col[2] = c;
            pkt.col[1] = c;
            pkt.col[0] = c;
        }
        draw_world_quad(&pkt, 0, 0);
    }
    VU1_addGSregister(0x47, 0x5360B);
}
