/* Computes a per-vertex 2D sphere-map texture coordinate from position and normal arrays. */
void compute_vertex_to_reference_sphere_map_uvs(int n, char *nrm, char *pos, int unused, float *out) {
    float a[4];
    float t[4];
    float r[4];
    float c[4];
    int i;
    for (i = 0; i < n; i++) {
        float *p = (float *)(i * 12 + (int)pos);
        float *q;
        float len;
        t[3] = 1.0f;
        t[0] = p[0];
        t[1] = p[1];
        t[2] = p[2];
        FastVecSub(a, fleet_camera_pos, t);
        vec_scale_to_length(a, a, 1.0f);
        c[3] = 1.0f;
        q = (float *)(i * 12 + (int)nrm);
        c[0] = q[0];
        c[1] = q[1];
        c[2] = q[2];
        vec_scale_to_length(c, c, 1.0f);
        FastVecScale(r, c, FastVecDot(c, a) * 2.0f);
        FastVecSub(r, a, r);
        vec_scale_to_length(r, r, 1.0f);
        r[2] += 1.0f;
        len = FastVecLength(r) * 2.0f;
        out[i * 2] = (r[0] / len + 0.5f) * 4.0f;
        out[i * 2 + 1] = (r[1] / len + 0.5f) * 4.0f;
    }
}
